ValidationRule.errorConditionFormula:
IF( $UserRole.Name = "System Administrator", FALSE,
AND( OR(ISCHANGED(Status__c), ISCHANGED(Approval_Status__c)),
AND( NOT( OR( ISPICKVAL(Approval_Status__c, "Conditionally Approved"), ISPICKVAL(Approval_Status__c, "Documents Required"), ISPICKVAL(Approval_Status__c, "Rejected"), ISPICKVAL(PRIORVALUE(Approval_Status__c), "Conditionally Approved"), ISPICKVAL(PRIORVALUE(Approval_Status__c), "Documents Required"), ISPICKVAL(PRIORVALUE(Approval_Status__c), "Rejected") ) ), OR( TEXT(Status__c) = "Reapplied", TEXT(PRIORVALUE(Status__c)) = "Reapplied", AND(TEXT(Status__c) = "Replied", TEXT(Approval_Status__c) = "New"), AND(TEXT(Status__c) = "Closed", TEXT(Approval_Status__c) = "New"), AND(TEXT(PRIORVALUE(Status__c)) = "Replied", TEXT(PRIORVALUE(Approval_Status__c)) = "New"), AND(TEXT(PRIORVALUE(Status__c)) = "Closed", TEXT(PRIORVALUE(Approval_Status__c)) = "New") ) ),
NOT( OR(
AND( TEXT(PRIORVALUE(Status__c)) = TEXT(Status__c), TEXT(PRIORVALUE(Approval_Status__c)) = TEXT(Approval_Status__c) ),
/* 0 -> 1 : New/New -> In Progress/New */ AND( TEXT(PRIORVALUE(Status__c)) = "New", TEXT(PRIORVALUE(Approval_Status__c)) = "New", ISPICKVAL(Status__c, "In Progress"), ISPICKVAL(Approval_Status__c, "New") ),
/* 1 -> 2 : In Progress/New -> Replied/New */ AND( TEXT(PRIORVALUE(Status__c)) = "In Progress", TEXT(PRIORVALUE(Approval_Status__c)) = "New", ISPICKVAL(Status__c, "Replied"), ISPICKVAL(Approval_Status__c, "New") ),
/* 2 -> 3 : Replied/New -> (Reapplied/New or Closed/New) */ AND( TEXT(PRIORVALUE(Status__c)) = "Replied", TEXT(PRIORVALUE(Approval_Status__c)) = "New", OR( AND(ISPICKVAL(Status__c, "Reapplied"), ISPICKVAL(Approval_Status__c, "New")), AND(ISPICKVAL(Status__c, "Closed"), ISPICKVAL(Approval_Status__c, "New")) ) ),
/* 3 -> 4 : Reapplied/New -> Reapplied/In Progress */ AND( TEXT(PRIORVALUE(Status__c)) = "Reapplied", TEXT(PRIORVALUE(Approval_Status__c)) = "New", ISPICKVAL(Status__c, "Reapplied"), ISPICKVAL(Approval_Status__c, "In Progress") ),
/* 4 -> 5 : Reapplied/In Progress -> Reapplied/Approved */ AND( TEXT(PRIORVALUE(Status__c)) = "Reapplied", TEXT(PRIORVALUE(Approval_Status__c)) = "In Progress", ISPICKVAL(Status__c, "Reapplied"), ISPICKVAL(Approval_Status__c, "Approved") ),
/* 5 -> 6 : Reapplied/Approved -> Replied/Approved */ AND( TEXT(PRIORVALUE(Status__c)) = "Reapplied", TEXT(PRIORVALUE(Approval_Status__c)) = "Approved", ISPICKVAL(Status__c, "Replied"), ISPICKVAL(Approval_Status__c, "Approved") ),
/* 6 -> 7 : Replied/Approved -> Closed/Approved */ AND( TEXT(PRIORVALUE(Status__c)) = "Replied", TEXT(PRIORVALUE(Approval_Status__c)) = "Approved", ISPICKVAL(Status__c, "Closed"), ISPICKVAL(Approval_Status__c, "Approved") ) ) ) ) )
